/**
 * NocoDB - Linkrow Resource - Zod Schema Factory
 * Exports a factory that unions all operation schemas for this resource.
 *
 * Schema helpers (z, expressionSchema, etc.) are passed as parameters
 * by the schema-validator, not imported from external files.
 *
 * @generated - CommonJS JavaScript for runtime loading
 */

const getLinkSchema = require('./operation_link.schema');
const getListSchema = require('./operation_list.schema');
const getUnlinkSchema = require('./operation_unlink.schema');

module.exports = function getSchema(helpers) {
  const { parameters, z } = helpers;
  // Apply operation default if not set
  const effectiveParams = parameters.operation === undefined ? { ...parameters, operation: 'list' } : parameters;
  return z.union([
    getLinkSchema({ ...helpers, parameters: effectiveParams }),
    getListSchema({ ...helpers, parameters: effectiveParams }),
    getUnlinkSchema({ ...helpers, parameters: effectiveParams }),
  ]);
};